import{z as i,x as A,o as n,c as d,q as l,j as o,D as t,d as E,s,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const N=JSON.parse('{"title":"语义熵与幻觉检测","description":"","frontmatter":{"title":"语义熵与幻觉检测","date":"2026-09-27T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/semantic-uncertainty.md","filePath":"llm/semantic-uncertainty.md","lastUpdated":1791413859000}'),p={name:"llm/semantic-uncertainty.md"};function m(u,a,D,c,h,f){const r=A("Mermaid");return n(),d("div",null,[a[2]||(a[2]=l('<h1 id="语义熵与幻觉检测" tabindex="-1">语义熵与幻觉检测 <a class="header-anchor" href="#语义熵与幻觉检测" aria-label="Permalink to &quot;语义熵与幻觉检测&quot;">​</a></h1><div class="epigraph"><p>模型「知道自己在编」的第一个信号藏在采样方差里：同题多答，说法聚成一团是笃定，散落一片是在猜——语义熵因此而生。</p><footer>—— 据 Kuhn–Gal–Farquhar「Semantic Uncertainty」ICLR 2023；Farquhar et al. Nature 2024 幻觉检测</footer></div><p><a href="/llm/emergent-abilities">能力涌现之争</a>讲的是测量的尺子，本课的尺子量「模型对自己输出的把握」。缺口是<strong>语义熵</strong>：不用 token 概率，而用<strong>语义等价类</strong>上的熵判断幻觉。它把「模型知道不知道」从玄学变成可测的采样统计量。本课不进信念表示的表征工程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>token 级困惑度失灵：「巴黎是法国的首都」与「法国的首都是巴黎」token 分布完全不同、语义同一——模型换一种说法时 token 熵飙升，但明明很笃定；反过来，流畅的胡编 token 概率却很高。缺口：<strong>在语义层面而非词面层面度量不确定性</strong>。要回答：怎么把采样聚成「意思」、怎么算熵、阈值怎么定。</p><p><span class="marginnote">术语翻译：语义熵 = 语义等价类上的熵 \\(H(\\text{意思})\\)，由 token 熵经「按含义归簇」聚合而来；隐式语义簇 = 用双向蕴含（NLI）判定「两答案是否同一意思」，免人工标注意义类。</span></p><p><span class="marginnote">数字实例：问「谁是《百年孤独》作者？」采 5 答：「加西亚·马尔克斯」×4、「加博（马尔克斯的笔名）」×1——NLI 判同簇，语义熵接近 0（全体落进单一语义簇），判笃定。若采出「马尔克斯 / 村上春树 / 是加西亚·马尔克斯吗 / 不知道」——质量分散进多个互斥簇，熵显著抬升，判幻觉候选。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四步流水线：采 N 个答案（温度 ≥ 0.5，N=5–10）；两两过 NLI 模型判「蕴含/矛盾」聚成等价类；在簇上算离散熵；与阈值比较。工程增强：对「我不确定/我不懂」类回答单列一簇（它们自己就是不确定性的口头表达）；长答案先抽关键声明再聚簇。全程无需改模型、无需训练——是推理侧的采样统计。</p>',9)),(n(),o(B,null,{default:t(()=>[s(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%90%8C%E9%A2%98%E9%87%87%E6%A0%B7%20N%20%E7%AD%94%22%5D%20--%3E%20B%5B%22%E4%B8%A4%E4%B8%A4%20NLI%20%E8%95%B4%E5%90%AB%E5%88%A4%E5%AE%9A%22%5D%0A%20%20B%20--%3E%20C%5B%22%E8%81%9A%E6%88%90%E8%AF%AD%E4%B9%89%E7%AD%89%E4%BB%B7%E7%B1%BB%22%5D%0A%20%20C%20--%3E%20D%5B%22%E7%B0%87%E4%B8%8A%E7%AE%97%E7%86%B5%20H%22%5D%0A%20%20D%20--%3E%20E%7B%22H%20%EF%BC%9E%20%E9%98%88%E5%80%BC%3F%22%7D%0A%20%20E%20--%3E%7C%22%E9%AB%98%E7%86%B5%22%7C%20F%5B%22%E5%B9%BB%E8%A7%89%E5%80%99%E9%80%89%20%E2%86%92%20%E5%85%9C%E5%BA%95%2F%E6%A3%80%E7%B4%A2%22%5D%0A%20%20E%20--%3E%7C%22%E4%BD%8E%E7%86%B5%22%7C%20G%5B%22%E6%94%BE%E8%A1%8C%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：问十个证人同一件事——十人说法一致（哪怕措辞不同）= 语义熵低，可信；十人给出三四个互相矛盾的版本 = 语义熵高，这段证词（哪怕条理最清晰的那份）都别信。词面困惑度在数「用词统一不统一」，语义熵在数「口径统一不统一」。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("为什么语义熵比 token 熵准：幻觉的典型形态是「模型把低置信的联想流畅地写成事实」——流畅性（token 概率）与真实性脱钩，而"),e("strong",null,"采样多样性"),E("与真实性挂钩：模型内部若有稳定答案，采样只是同一意思的措辞抖动（簇紧）；若在猜，采样会落到不同的语义分支（簇散）。数学上这是「对预测分布做等价类压缩后熵下降」——token 熵把「措辞熵」与「语义熵」混在一起，归簇把前者剥掉。Nature 2024 的扩展用语义熵对"),e("strong",null,"首 token 级"),E("的答案前缀打分，可实时预警而非事后判卷；阈值按任务校准（AUC 0.8+ 常见），检索兜底与「拒答」是高熵的自然后继动作。")],-1)),(n(),o(B,null,{default:t(()=>[s(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E4%B8%BA%E4%BD%95%20token%20%E7%86%B5%E5%A4%B1%E7%81%B5%3F%22%7D%20--%3E%20R%5B%22%E6%8D%A2%E8%AF%B4%E6%B3%95%20%3D%20token%20%E5%A4%A7%E5%8F%98%22%5D%0A%20%20R%20--%3E%20S%5B%22%E6%8E%AA%E8%BE%9E%E7%86%B5%E6%B7%B9%E6%B2%A1%E8%AF%AD%E4%B9%89%E7%86%B5%22%5D%0A%20%20T%7B%22%E5%BD%92%E7%B0%87%E4%B8%BA%E4%BD%95%E6%9C%89%E6%95%88%3F%22%7D%20--%3E%20U%5B%22NLI%20%E5%88%A4%E5%90%8C%E4%B9%89%22%5D%0A%20%20U%20--%3E%20V%5B%22%E5%8E%8B%E7%BC%A9%E6%8E%89%E6%8E%AA%E8%BE%9E%E8%87%AA%E7%94%B1%E5%BA%A6%22%5D%0A%20%20V%20--%3E%20W%5B%22%E5%89%A9%E4%B8%8B%E7%9A%84%E7%86%B5%20%3D%20%E7%9C%9F%E4%B8%8D%E7%A1%AE%E5%AE%9A%22%5D%0A%20%20W%20--%3E%20X%5B%22%E9%AB%98%E7%86%B5%20%E2%86%92%20%E6%A3%80%E7%B4%A2%E5%85%9C%E5%BA%95%20%2F%20%E6%8B%92%E7%AD%94%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">常见误区：拿「一次生成的 logprob」判幻觉——单次采样的概率与正确性几乎不相关，必看分布；另一误区是 NLI 模型自身偏置直接透传——NLI 误判「Paris/巴黎」为矛盾会把低熵错算成高熵，跨语任务先测 NLI 自己。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>语义熵抓「模型内部不一致」型幻觉（瞎编事实、张冠李戴），抓不住「内部一致但全错」型（系统性偏见、训练数据集体错误——采样十次错得整整齐齐，熵为零）。NLI 聚簇的长文本成本：两两比对 \\(O(N^2)\\)，答案长需先抽声明。阈值随领域漂移，医疗/法务要用各自校准集。与 RLHF 的互动：对齐后的模型学会「统一口径地说错话」时此法失效加剧——这是「对齐税」在不确定性度量上的体现。与<a href="/llm/conformal-prediction-llm">保形预测</a>的互补：保形给「错误率上限」的分布无关保证，语义熵给「这一次在不在猜」的即时信号——一个管审计、一个管运行。</p><p><span class="marginnote">直觉类比：语义熵像「多问几个银行柜员确认汇率」——十个柜员报价一致就放心（低熵），报价五花八门说明其中有编造（高熵）；但若全行系统性地用错汇率表（一致性错误），问一百个柜员也白问——这是它的边界。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>语义熵 = 语义等价类上的熵；NLI 归簇剥掉措辞自由度。</li><li>流畅性 ≠ 可信度，采样多样性才是模型内部把握的信号。</li><li>抓不一致型幻觉，抓不住一致性错误；阈值须按域校准。</li><li>出处：Kuhn–Gal–Farquhar ICLR 2023；Farquhar et al. Nature 2024。</li></ul>',6))])}const _=i(p,[["render",m]]);export{N as __pageData,_ as default};
